import csv
import json
import os

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(SUB_DIR, "solution.csv")
MODEL_PATH = os.path.join(SUB_DIR, "model.md")
LOG_PATH = os.path.join(SUB_DIR, "solve_log.md")


def read_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        config = json.load(f)

    curbs = {}
    curb_order = []
    with open(os.path.join(DATA_DIR, "curbs.csv")) as f:
        for row in csv.DictReader(f):
            c = row["curb_id"]
            curbs[c] = {
                "district": row["district"],
                "bay_count": int(row["bay_count"]),
                "daily_visit_limit": int(row["daily_visit_limit"]),
                "permit_cost_per_visit": float(row["permit_cost_per_visit"]),
            }
            curb_order.append(c)

    slots = {}
    slot_order = []
    with open(os.path.join(DATA_DIR, "slots.csv")) as f:
        for row in csv.DictReader(f):
            s = row["slot_id"]
            slots[s] = {
                "slot_index": int(row["slot_index"]),
                "start_time": row["start_time"],
                "congestion_multiplier": float(row["congestion_multiplier"]),
            }
            slot_order.append(s)

    capacity = {}
    with open(os.path.join(DATA_DIR, "curb_slot_capacity.csv")) as f:
        for row in csv.DictReader(f):
            capacity[(row["curb_id"], row["slot_id"])] = float(row["capacity_minutes"])

    jobs = {}
    job_order = []
    with open(os.path.join(DATA_DIR, "delivery_jobs.csv")) as f:
        for row in csv.DictReader(f):
            j = row["job_id"]
            jobs[j] = {
                "district": row["district"],
                "packages": int(row["packages"]),
                "dwell_minutes": float(row["dwell_minutes"]),
                "earliest_slot": row["earliest_slot"],
                "latest_slot": row["latest_slot"],
                "priority_weight": float(row["priority_weight"]),
                "temperature_control": int(row["temperature_control"]),
                "unserved_penalty": float(row["unserved_penalty"]),
            }
            job_order.append(j)

    eligibility = {}
    with open(os.path.join(DATA_DIR, "job_curb_eligibility.csv")) as f:
        for row in csv.DictReader(f):
            j = row["job_id"]
            c = row["curb_id"]
            eligibility[(j, c)] = {
                "walk_minutes": float(row["walk_minutes"]),
                "handling_cost": float(row["handling_cost"]),
                "temperature_ok": int(row["temperature_ok"]),
            }

    return config, curbs, curb_order, slots, slot_order, capacity, jobs, job_order, eligibility


def write_model_md(path):
    text = """# Curbside Delivery Slot Coordination - Mathematical Model

## Sets
- J: delivery jobs
- C: curbs
- S: slots (ordered)
- E: eligible (job, curb) pairs

## Parameters
- dwell_j, pk_j, w_j, pen_j, tc_j per job
- cap_{c,s}, L_c, perm_c per curb/slot
- walk_{j,c}, h_{j,c}, tOK_{j,c} per eligible pair
- cong_s per slot
- beta = walk_cost_per_package_minute, alpha = lateness_cost_per_priority_slot

## Variables
- x_{j,c,s} in {0,1}: assign job j to curb c in slot s (eligible pairs, temp-compatible, slot in window)
- u_j in {0,1}: job j unserved

## Objective (minimize)
Sum over feasible (j,c,s): h_{j,c} + beta*pk_j*walk_{j,c} + dwell_j*cong_s + perm_c + alpha*w_j*(idx(s)-idx(earliest_j))
plus w_j*pen_j*u_j.

## Constraints
1. sum_{c,s} x_{j,c,s} + u_j = 1 for all j
2. sum_j dwell_j*x_{j,c,s} <= cap_{c,s} for all (c,s)
3. sum_{j,s} x_{j,c,s} <= L_c for all c
"""
    with open(path, "w") as f:
        f.write(text)


def main():
    os.makedirs(SUB_DIR, exist_ok=True)
    config, curbs, curb_order, slots, slot_order, capacity, jobs, job_order, eligibility = read_data()
    write_model_md(MODEL_PATH)

    beta = float(config.get("walk_cost_per_package_minute", 0.041))
    alpha = float(config.get("lateness_cost_per_priority_slot", 4.7))
    tol = float(config.get("feasibility_tolerance", 1e-5))

    slot_idx = {s: slots[s]["slot_index"] for s in slot_order}

    # Build feasible (j, c, s) triples and objective coefficients
    triples = []
    obj_coeff = {}
    for j in job_order:
        job = jobs[j]
        e_idx = slot_idx[jobs[j]["earliest_slot"]]
        l_idx = slot_idx[jobs[j]["latest_slot"]]
        for (jj, c), el in eligibility.items():
            if jj != j:
                continue
            if job["temperature_control"] == 1 and el["temperature_ok"] != 1:
                continue
            for s in slot_order:
                si = slot_idx[s]
                if si < e_idx or si > l_idx:
                    continue
                if (c, s) not in capacity:
                    continue
                key = (j, c, s)
                cost = (
                    el["handling_cost"]
                    + beta * job["packages"] * el["walk_minutes"]
                    + job["dwell_minutes"] * slots[s]["congestion_multiplier"]
                    + curbs[c]["permit_cost_per_visit"]
                    + alpha * job["priority_weight"] * (si - e_idx)
                )
                obj_coeff[key] = cost
                triples.append(key)

    model = Model("curbside_delivery_slot_coordination")
    model.setParam("gaprel", 0.0005)

    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    x = {}
    for (j, c, s) in triples:
        x[(j, c, s)] = model.addVar(name=f"x_{j}_{c}_{s}", vtype="B", lb=0.0, ub=1.0, obj=0.0)

    u = {}
    for j in job_order:
        u[j] = model.addVar(name=f"u_{j}", vtype="B", lb=0.0, ub=1.0, obj=0.0)

    # Objective: explicit expression
    obj_expr = quicksum([obj_coeff[k] * x[k] for k in triples])
    obj_expr += quicksum([jobs[j]["priority_weight"] * jobs[j]["unserved_penalty"] * u[j] for j in job_order])
    model.setObjective(obj_expr, sense="minimize")

    # Constraint 1: exactly one outcome per job
    for j in job_order:
        lhs = quicksum([x[k] for k in triples if k[0] == j]) + u[j]
        model.addCons(lhs == 1, name=f"one_outcome_{j}")

    # Constraint 2: curb-slot capacity
    cap_cons = {}
    for c in curb_order:
        for s in slot_order:
            if (c, s) not in capacity:
                continue
            terms = [(k, jobs[k[0]]["dwell_minutes"]) for k in triples if k[1] == c and k[2] == s]
            if not terms:
                continue
            cons = model.addCons(
                quicksum([d * x[k] for (k, d) in terms]) <= capacity[(c, s)],
                name=f"cap_{c}_{s}",
            )
            cap_cons[(c, s)] = cons

    # Constraint 3: daily visit limit
    for c in curb_order:
        terms = [k for k in triples if k[1] == c]
        if not terms:
            continue
        model.addCons(
            quicksum([x[k] for k in terms]) <= curbs[c]["daily_visit_limit"],
            name=f"visitlimit_{c}",
        )

    status = "unknown"
    obj_val = None
    try:
        model.optimize()
        status = model.getStatus()
        if model.getNSols() > 0:
            obj_val = model.getObjVal()
    except Exception as e:
        print(f"Solver error: {e}")
        status = f"error: {e}"

    # Extract solution
    assignment = {}
    unserved = set()
    if model.getNSols() > 0:
        for k in triples:
            v = model.getVal(x[k])
            if v is not None and v > 0.5:
                assignment[k] = int(round(v))
        for j in job_order:
            v = model.getVal(u[j])
            if v is not None and v > 0.5:
                unserved.add(j)

    # Repair: ensure every job has exactly one outcome
    for j in job_order:
        assigned = [k for k in assignment if k[0] == j]
        if j in unserved:
            if assigned:
                # drop unserved marker; keep assignment
                unserved.discard(j)
        else:
            if not assigned:
                # mark unserved if no assignment
                unserved.add(j)
            elif len(assigned) > 1:
                # keep the cheapest one
                assigned.sort(key=lambda k: obj_coeff[k])
                for k in assigned[1:]:
                    del assignment[k]

    # Validation
    violations = []
    job_outcome = {}
    for j in job_order:
        n_assign = sum(1 for k in assignment if k[0] == j)
        n_unserved = 1 if j in unserved else 0
        if n_assign + n_unserved != 1:
            violations.append(f"job {j}: {n_assign} assignments, {n_unserved} unserved")

    cap_usage = {}
    visit_count = {}
    for (j, c, s) in assignment:
        job = jobs[j]
        e_idx = slot_idx[jobs[j]["earliest_slot"]]
        l_idx = slot_idx[jobs[j]["latest_slot"]]
        si = slot_idx[s]
        if si < e_idx or si > l_idx:
            violations.append(f"job {j}: slot {s} outside window")
        if (j, c) not in eligibility:
            violations.append(f"job {j}: curb {c} not eligible")
        elif job["temperature_control"] == 1 and eligibility[(j, c)]["temperature_ok"] != 1:
            violations.append(f"job {j}: curb {c} not temp compatible")
        cap_usage[(c, s)] = cap_usage.get((c, s), 0.0) + job["dwell_minutes"]
        visit_count[c] = visit_count.get(c, 0) + 1

    for (c, s), used in cap_usage.items():
        if (c, s) in capacity and used > capacity[(c, s)] + tol:
            violations.append(f"capacity violated at {c},{s}: {used} > {capacity[(c, s)]}")
    for c, cnt in visit_count.items():
        if cnt > curbs[c]["daily_visit_limit"]:
            violations.append(f"visit limit violated at {c}: {cnt} > {curbs[c]['daily_visit_limit']}")

    # Recompute objective from extracted solution
    total_cost = 0.0
    for (j, c, s) in assignment:
        total_cost += obj_coeff[(j, c, s)]
    for j in unserved:
        total_cost += jobs[j]["priority_weight"] * jobs[j]["unserved_penalty"]

    print(f"Status: {status}")
    print(f"Solver objective: {obj_val}")
    print(f"Extracted solution objective: {total_cost:.8f}")
    print(f"Assignments: {len(assignment)}, Unserved: {len(unserved)}")
    if violations:
        print("VIOLATIONS:")
        for v in violations:
            print("  ", v)
    else:
        print("All validation checks passed.")

    # Write solution.csv
    with open(SOLUTION_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "job_id", "curb_id", "slot_id", "value"])
        for j in job_order:
            for (jj, c, s) in assignment:
                if jj == j:
                    w.writerow(["assignment", j, c, s, "1"])
        for j in job_order:
            if j in unserved:
                w.writerow(["unserved", j, "", "", "1"])

    # Write solve log
    log_lines = [
        "# Solve Log - curbside_delivery_slot_coordination",
        "",
        "## Commands",
        "- `python /app/submissions/solve.py`",
        "",
        "## Solver",
        f"- PySCIPOpt, gaprel=0.0005, time_limit={time_limit}s",
        f"- Status: {status}",
        f"- Solver objective: {obj_val}",
        f"- Extracted solution objective: {total_cost:.8f}",
        f"- Assignments: {len(assignment)}, Unserved: {len(unserved)}",
        "",
        "## Validation",
    ]
    if violations:
        log_lines.append("Violations found:")
        for v in violations:
            log_lines.append(f"- {v}")
    else:
        log_lines.append("- All validation checks passed (one outcome per job, eligibility, windows, capacity, visit limits).")
    log_lines.append(f"- Output schema: row_type,job_id,curb_id,slot_id,value")
    log_lines.append(f"- Solution file: {SOLUTION_PATH}")
    with open(LOG_PATH, "w") as f:
        f.write("\n".join(log_lines) + "\n")

    model.free()


if __name__ == "__main__":
    main()
